'use strict';
const $=id=>document.getElementById(id);
const sample='A quiet room. A good story. A little time to yourself.\n\nHold your mouse or finger on the reading area, and let the words come to you. Release whenever you need a moment. There is no finish line here, just the next word. Read at your own pace.';
let words=[],index=0,timer=null,playing=false,finished=false,keyboard=false,uploadVersion=0,title="Sample text",paragraphVersion=1;
const pointers=new Set();
let activeBook=null, autosaveTimer=null, storageQueue=Promise.resolve();
function queueStorage(work){const job=storageQueue.then(work);storageQueue=job.catch(()=>{});return job;}
function storageError(error){$('bookmarkMessage').textContent='Could not save on this device: '+error.message;}
function beginLocalBook(){const snapshot={title,words,index,paragraphVersion,speed:Number($('speed').value)};activeBook=queueStorage(async()=>{const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(snapshot.words.map(({text,parts})=>({text,parts})))));const id=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');await api('/'+id,{method:'PUT',body:JSON.stringify(snapshot)});await refreshBookmarks();$('bookmarkMessage').textContent='Document saved on this device. Your position saves automatically.';return id;});activeBook.catch(storageError);}
function savePosition(){clearTimeout(autosaveTimer);autosaveTimer=null;if(!activeBook)return Promise.resolve();const book=activeBook,snapshot={index,speed:Number($('speed').value),finished};return queueStorage(async()=>{const id=await book;await api('/'+id,{method:'PATCH',body:JSON.stringify(snapshot)});if(!playing)await refreshBookmarks();}).catch(storageError);}
function scheduleLocalSave(){if(!activeBook)return;if(!playing){savePosition();return;}if(!autosaveTimer)autosaveTimer=setTimeout(savePosition,1000);}
$('text').value=sample;
function delay(word,speed=Number($('speed').value)){const text=typeof word==='string'?word:word.text;const clean=text.replace(/["\u201d\u2019'\])}]+$/u,'');const beat=60000/speed;const multiplier=/[.!?…]$/u.test(clean)?4:/[,;:]$/u.test(clean)?2.5:1;const hyphenated=/[-\u00ad\u2010\u2011\u2014\ufe63\uff0d]/u.test(text)&&/[\p{L}\p{N}]/u.test(text);const length=(text.match(/[\p{L}\p{N}]/gu)||[]).length;const extra=hyphenated?1+length/4:0;return beat*(multiplier+extra+(word.paragraphEnd?3:0));}
function plainText(tokens){return tokens.map((w,i)=>w.text+(i<tokens.length-1?(w.paragraphEnd?'\n\n':' '):'')).join('');}

function fit(){const el=$('word');el.style.fontSize='';const size=parseFloat(getComputedStyle(el).fontSize);if(el.scrollWidth>$('pad').clientWidth-44)el.style.fontSize=Math.max(8,size*($('pad').clientWidth-44)/el.scrollWidth)+'px';}
function render(){ $('word').replaceChildren(); for(const part of (words[index]?.parts||[{text:'Ready.',italic:false}])){const span=document.createElement(part.italic?'em':'span');span.textContent=part.text;$('word').append(span);} $('position').textContent=words.length?`${index+1} / ${words.length.toLocaleString()} words`:'0 words';const pct=finished?100:words.length>1?Math.round(index/(words.length-1)*1000)/10:0;$('percent').textContent=pct+'%';$('progress').value=pct;$('progress').setAttribute('aria-valuetext',`${pct}% · word ${words.length?index+1:0} of ${words.length}`);$('status').textContent=finished?'Finished':playing?'Reading':index===0?'Ready to read':'Paused';$('pad').classList.toggle('active',playing);$('holdHint').textContent=finished?'Finished · rewind or jump to 0% to read again':playing?'Release to pause & rewind 10':'Press and hold here to read';fit();scheduleLocalSave();}
function pause(){clearTimeout(timer);timer=null;playing=false;render();}
function schedule(){clearTimeout(timer);timer=setTimeout(()=>{if(!playing)return;if(index>=words.length-1){finished=true;pause();return;}index++;render();schedule();},delay(words[index]));}
function start(){if(playing||!words.length||finished)return;playing=true;render();schedule();}
function seek(amount){pause();index=Math.max(0,Math.min(words.length-1,index+amount));finished=false;render();}
function load(input,label,saveLocally=true){const next=typeof input==='string'?tokenize([{text:input}]):input;if(!next.length){$('message').textContent='Add some text before loading the reader.';return false;}resetInput();activeBook=null;words=next;index=0;finished=false;title=label;paragraphVersion=1;$('sourceCount').textContent=label;$('message').textContent=`${words.length.toLocaleString()} words loaded. Hold the reading area to begin.`;render();if(saveLocally)beginLocalBook();return true;}
let importedText='',importedWords=null;
$('clearText').onclick=()=>{uploadVersion++;$('text').value='';importedText='';importedWords=null;$('file').value='';$('message').textContent='Paste area cleared. Add new text when ready.';$('text').focus({preventScroll:true});};
$('load').onclick=()=>{uploadVersion++;const text=$('text').value;load(importedWords&&text===importedText?importedWords:text,importedWords&&text===importedText?title:'Pasted text');};
function jumpToPercent(value){const pct=Number(value);if(!Number.isFinite(pct)||!words.length)return;resetInput();index=Math.round((words.length-1)*Math.max(0,Math.min(100,pct))/100);finished=false;render();}
$('progress').addEventListener('pointerdown',resetInput);
$('progress').addEventListener('input',e=>jumpToPercent(e.target.value));
$('jumpForm').addEventListener('submit',e=>{e.preventDefault();if($('jumpPercent').value.trim()===''||!$('jumpPercent').checkValidity())return;jumpToPercent($('jumpPercent').value);});

$('speed').oninput=()=>{$('speedValue').innerHTML=$('speed').value+' <small>WPM</small>';if(playing)schedule();scheduleLocalSave();};
const pad=$('pad');
pad.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();pad.focus({preventScroll:true});pointers.add(e.pointerId);pad.setPointerCapture(e.pointerId);if(pointers.size===1)start();});
function release(e){if(!pointers.delete(e.pointerId))return;if(!pointers.size)seek(-10);}
function cancelPointer(e){if(!pointers.delete(e.pointerId))return;if(!pointers.size)pause();}
window.addEventListener('pointerup',release);window.addEventListener('pointercancel',cancelPointer);pad.addEventListener('lostpointercapture',cancelPointer);pad.addEventListener('contextmenu',e=>e.preventDefault());
let wheelAt=-Infinity;
pad.addEventListener('wheel',e=>{e.preventDefault();if(!e.deltaY)return;const now=performance.now();if(now-wheelAt<140)return;wheelAt=now;seek(e.deltaY>0?5:-5);},{passive:false});
pad.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();if(!e.repeat){keyboard=true;start();}}if(e.code==='ArrowLeft'||e.code==='ArrowRight'){e.preventDefault();seek(e.code==='ArrowLeft'?-5:5);}});
window.addEventListener('keyup',e=>{if(e.code==='Space'&&keyboard){keyboard=false;seek(-10);}});
function resetInput(){pointers.clear();keyboard=false;pause();}window.addEventListener('blur',resetInput);document.addEventListener('visibilitychange',()=>{if(document.hidden)resetInput();});pad.addEventListener('blur',resetInput);window.addEventListener('resize',fit);
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;resetInput();const version=++uploadVersion;$('message').textContent='Opening document…';try{if(file.size>50*1024*1024)throw Error('Choose a file smaller than 50 MB, or upload one chapter at a time.');const ext=file.name.split('.').pop().toLowerCase();if(!['docx','epub','txt','pdf'].includes(ext))throw Error('Please use .docx, .epub, .pdf, or .txt. Save older .doc files as .docx first.');const next=ext==='txt'?tokenize([{text:await file.text()}]):ext==='pdf'?await readPdf(await file.arrayBuffer()):ext==='epub'?await readEpub(await file.arrayBuffer()):await readDocx(await file.arrayBuffer());if(version!==uploadVersion)return;if(load(next,file.name)){importedWords=next;importedText=plainText(next);$('text').value=importedText;$('message').textContent=`${file.name} · ${words.length.toLocaleString()} words loaded automatically. Hold the reading box to begin. ${next.importNotice||'Original italics retained in the reader.'}`;$('status').textContent='Document ready to read';pad.scrollIntoView({behavior:'auto',block:'center'});pad.focus({preventScroll:true});}}catch(error){if(version===uploadVersion)$('message').textContent=error instanceof RangeError?'This file appears damaged or too large. Try a fresh copy.':error.message;}finally{e.target.value='';}};
function openBookmarkDb(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('This browser cannot save bookmarks. Use a browser with site storage enabled.'));return;}let settled=false;const request=indexedDB.open('speedy-readr-bookmarks',1);request.onupgradeneeded=()=>{const db=request.result;db.createObjectStore('books',{keyPath:'id'});db.createObjectStore('positions',{keyPath:'id'});};request.onerror=()=>reject(request.error);request.onblocked=()=>{settled=true;reject(Error('Close other Speedy Readr tabs, then try again.'));};request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>db.close();if(settled){db.close();return;}resolve(db);};});}
async function api(path,options={}){let db;try{db=await openBookmarkDb();return await new Promise((resolve,reject)=>{const saving=['PUT','PATCH','DELETE'].includes(options.method),id=path.replace(/^\//,'');const tx=db.transaction(['books','positions'],saving?'readwrite':'readonly');let result;tx.oncomplete=()=>resolve(result);tx.onabort=()=>reject(tx.error||Error('Bookmark storage was interrupted. Please try again.'));tx.onerror=()=>{};
if(options.method==='DELETE'){tx.objectStore('books').delete(id);tx.objectStore('positions').delete(id);result={deleted:true};}
else if(options.method==='PATCH'){const saved=JSON.parse(options.body);const store=tx.objectStore('positions');const request=store.get(id);request.onsuccess=()=>{if(!request.result){tx.abort();return;}store.put({...request.result,...saved,updated:Date.now()});result={saved:true};};}
else if(saving){const saved=JSON.parse(options.body);tx.objectStore('books').put({id,...saved});tx.objectStore('positions').put({id,title:saved.title,index:saved.index,speed:saved.speed,finished:!!saved.finished,updated:Date.now()});result={saved:true};}
else if(!path){const request=tx.objectStore('positions').getAll();request.onsuccess=()=>{result=request.result.sort((a,b)=>b.updated-a.updated);};}
else{const request=tx.objectStore('books').get(id);request.onsuccess=()=>{if(!request.result){reject(Error('This bookmark is no longer stored in this browser.'));return;}result=request.result;const position=tx.objectStore('positions').get(id);position.onsuccess=()=>{if(position.result)result={...result,...position.result};};};}
});}catch(error){if(error.name==='QuotaExceededError')throw Error('This browser has run out of storage. Free up device space or save a smaller document.');if(['SecurityError','InvalidStateError','UnknownError','NotAllowedError'].includes(error.name))throw Error('Browser storage is unavailable. Allow site data and try again in a regular browser window.');throw error;}finally{db?.close();}}
async function refreshBookmarks(){try{const list=await api('');const select=$('bookmarks');const selected=select.value;select.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=list.length?'Choose a saved bookmark':'No bookmarks yet';select.append(placeholder);for(const item of list){const option=document.createElement('option');option.value=item.id;option.textContent=`${item.title} · word ${Number(item.index)+1}`;select.append(option);}if(list.some(item=>item.id===selected))select.value=selected;$('restoreBookmark').disabled=!list.length;$('deleteBookmark').disabled=!select.value;}catch(error){$('bookmarkMessage').textContent=error.message;}}
$('bookmarks').addEventListener('change',()=>{$('deleteBookmark').disabled=!$('bookmarks').value;});
$('deleteBookmark').onclick=async()=>{const id=$('bookmarks').value;if(!id)return;resetInput();uploadVersion++;const button=$('deleteBookmark');button.disabled=true;try{const current=activeBook;if(current&&await current.catch(()=>null)===id&&activeBook===current){clearTimeout(autosaveTimer);autosaveTimer=null;activeBook=null;}await queueStorage(()=>api('/'+id,{method:'DELETE'}));await refreshBookmarks();$('bookmarkMessage').textContent='Saved document and bookmark deleted from this device.';}catch(error){storageError(error);}finally{button.disabled=!$('bookmarks').value;}};
$('saveBookmark').onclick=async()=>{resetInput();if(!activeBook)beginLocalBook();await savePosition();};
$('restoreBookmark').onclick=async()=>{const id=$('bookmarks').value;if(!id){$('bookmarkMessage').textContent='Choose a bookmark first.';return;}resetInput();const version=++uploadVersion;$('restoreBookmark').disabled=true;try{const saved=await api('/'+id);if(version!==uploadVersion)return;load(saved.words,saved.title,false);paragraphVersion=saved.paragraphVersion||0;index=Math.max(0,Math.min(words.length-1,saved.index||0));finished=!!saved.finished;activeBook=Promise.resolve(id);$('speed').value=saved.speed||250;$('speed').oninput();importedWords=saved.words;importedText=plainText(saved.words);$('text').value=importedText;render();$('bookmarkMessage').textContent=`Resumed at word ${index+1}.`+(saved.paragraphVersion? '':' This older bookmark has no paragraph information. Re-upload the original document to enable paragraph pauses, then bookmark your spot again.');}catch(error){$('bookmarkMessage').textContent=error.message;}finally{$('restoreBookmark').disabled=false;}};
window.addEventListener('pagehide',()=>{resetInput();savePosition();});
load(sample,'Sample text',false);$('message').textContent='Try the sample, or add something of your own.';refreshBookmarks();
